                    { 1, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Połóż się na ławce, stopy oprzyj o podłogę, łopatki ściągnij i przyciśnij do ławki. Opuść sztangę kontrolowanym ruchem do dolnej części klatki piersiowej, a następnie wypchnij ją w górę do wyprostu łokci. Nie odbijaj sztangi od klatki i nie odrywaj pośladków od ławki.", "Intermediate", "Barbell", false, "Klatka piersiowa, triceps, przedni akton barków", "Wyciskanie sztangi na ławce płaskiej", null },
                    { 2, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ustaw oparcie ławki pod kątem 30–45°. Opuść sztangę do górnej części klatki piersiowej i wypchnij ją pionowo w górę. Łopatki trzymaj ściągnięte przez całą serię.", "Intermediate", "Barbell", false, "Górna część klatki piersiowej, przedni akton barków, triceps", "Wyciskanie sztangi na ławce skośnej", null },
                    { 3, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Połóż się na ławce z hantlami trzymanymi nad klatką piersiową. Opuszczaj je po łuku na boki, aż łokcie znajdą się nieco poniżej linii ławki, a potem wypchnij je w górę, zbliżając hantle do siebie.", "Beginner", "Dumbbell", false, "Klatka piersiowa, triceps, przedni akton barków", "Wyciskanie hantli na ławce płaskiej", null },
                    { 4, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ustaw oparcie ławki pod kątem 30–45°. Opuść hantle do wysokości górnej części klatki piersiowej, łokcie prowadź pod kątem około 45° do tułowia. Wypchnij hantle w górę do wyprostu ramion.", "Beginner", "Dumbbell", false, "Górna część klatki piersiowej, przedni akton barków, triceps", "Wyciskanie hantli na ławce skośnej", null },
                    { 5, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Trzymaj hantle nad klatką piersiową z lekko ugiętymi łokciami. Opuszczaj ramiona szeroko na boki, aż poczujesz rozciągnięcie klatki, i wróć tym samym łukiem. Kąt w łokciach nie zmienia się przez cały ruch.", "Beginner", "Dumbbell", false, "Klatka piersiowa, przedni akton barków", "Rozpiętki z hantlami na ławce płaskiej", null },
                    { 6, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań w środku bramy z uchwytami górnych wyciągów w dłoniach i pochyl lekko tułów. Prowadź dłonie łukiem w dół i do środka, aż spotkają się przed biodrami. Powoli wróć, kontrolując ciężar.", "Intermediate", "Cable", false, "Klatka piersiowa, przedni akton barków", "Krzyżowanie linek wyciągu na bramie", null },
                    { 7, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dłonie ustaw nieco szerzej niż barki, ciało trzymaj w jednej linii od głowy do pięt. Opuść się, aż klatka piersiowa znajdzie się tuż nad podłogą, i wypchnij się do wyprostu ramion. Łatwiejsza wersja: z kolanami opartymi o podłogę.", "Beginner", "Bodyweight", false, "Klatka piersiowa, triceps, przedni akton barków, mięśnie brzucha", "Pompki", null },
                    { 8, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Podeprzyj się na poręczach na wyprostowanych ramionach. Pochyl tułów lekko do przodu i opuszczaj się, aż ramiona znajdą się mniej więcej równolegle do podłogi, a potem wypchnij się w górę. Nie schodź głębiej, jeśli czujesz ból barków.", "Intermediate", "Bodyweight", false, "Dolna część klatki piersiowej, triceps, przedni akton barków", "Pompki na poręczach (dipy)", null },
                    { 9, "Chest", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ustaw siedzisko tak, aby uchwyty znajdowały się na wysokości środka klatki piersiowej. Wypchnij uchwyty do przodu do prawie pełnego wyprostu łokci i powoli wróć. Plecy i łopatki trzymaj przy oparciu.", "Beginner", "Machine", false, "Klatka piersiowa, triceps, przedni akton barków", "Wyciskanie na maszynie siedząc", null },
                    { 10, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań ze stopami na szerokość bioder, sztanga nad środkiem stopy. Chwyć gryf, napnij brzuch i plecy, zachowując neutralne ustawienie kręgosłupa. Podnieś sztangę, prostując jednocześnie biodra i kolana i prowadząc gryf blisko nóg; opuść ją tą samą drogą.", "Advanced", "Barbell", false, "Prostowniki grzbietu, pośladki, mięśnie dwugłowe ud, czworogłowe ud, przedramiona", "Martwy ciąg klasyczny", null },
                    { 11, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Chwyć drążek nachwytem nieco szerzej niż barki. Z pełnego zwisu podciągnij się, aż broda znajdzie się nad drążkiem, prowadząc łokcie w dół. Opuszczaj się powoli do pełnego wyprostu ramion.", "Intermediate", "Bodyweight", false, "Najszerszy grzbietu, biceps, mięśnie obłe", "Podciąganie na drążku nachwytem", null },
                    { 12, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Chwyć drążek podchwytem na szerokość barków. Podciągnij się, aż broda znajdzie się nad drążkiem, prowadząc łokcie wzdłuż tułowia. Opuszczaj się powoli, bez bujania nogami.", "Intermediate", "Bodyweight", false, "Najszerszy grzbietu, biceps", "Podciąganie na drążku podchwytem", null },
                    { 13, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Pochyl tułów do około 45° przy prostych plecach i lekko ugiętych kolanach. Przyciągnij sztangę do dolnej części brzucha, ściągając łopatki, a następnie opuść ją do wyprostu ramion. Tułów pozostaje nieruchomy.", "Intermediate", "Barbell", false, "Najszerszy grzbietu, mięśnie czworoboczne i równoległoboczne, tylny akton barków", "Wiosłowanie sztangą w opadzie tułowia", null },
                    { 14, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Oprzyj kolano i dłoń o ławkę, plecy trzymaj równolegle do podłogi. Przyciągnij hantel do biodra, prowadząc łokieć blisko tułowia, i powoli go opuść. Nie skręcaj tułowia.", "Beginner", "Dumbbell", false, "Najszerszy grzbietu, mięśnie równoległoboczne, tylny akton barków", "Wiosłowanie hantlem jednorącz", null },
                    { 15, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Usiądź z udami zablokowanymi pod wałkami i chwyć drążek szeroko. Ściągnij go do górnej części klatki piersiowej, prowadząc łokcie w dół i lekko odchylając tułów. Powoli wróć do wyprostu ramion.", "Beginner", "Cable", false, "Najszerszy grzbietu, biceps, mięśnie obłe", "Ściąganie drążka wyciągu górnego do klatki", null },
                    { 16, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Usiądź z lekko ugiętymi kolanami i wyprostowanymi plecami. Przyciągnij uchwyt do brzucha, ściągając łopatki, i powoli wróć do wyprostu ramion. Nie odchylaj tułowia, aby pomóc sobie w ruchu.", "Beginner", "Cable", false, "Mięśnie równoległoboczne, najszerszy grzbietu, czworoboczne", "Przyciąganie linki wyciągu dolnego siedząc", null },
                    { 17, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Oprzyj klatkę piersiową o podkładkę i chwyć uchwyty. Przyciągnij je do tułowia, ściągając łopatki, zatrzymaj ruch na chwilę i powoli wróć.", "Beginner", "Machine", false, "Mięśnie równoległoboczne, najszerszy grzbietu, tylny akton barków", "Wiosłowanie na maszynie", null },
                    { 18, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ustaw biodra tuż nad krawędzią podkładki, a stopy zablokuj pod wałkami. Opuść tułów w dół z prostymi plecami, a następnie unieś go do linii prostej z nogami. Nie przeprostowuj kręgosłupa w górnej fazie.", "Beginner", "Bodyweight", false, "Prostowniki grzbietu, pośladki, mięśnie dwugłowe ud", "Wznosy tułowia na ławce rzymskiej", null },
                    { 19, "Back", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań prosto z hantlami trzymanymi wzdłuż tułowia. Unieś barki pionowo w górę w stronę uszu, zatrzymaj ruch na chwilę i powoli je opuść. Nie krąż barkami.", "Beginner", "Dumbbell", false, "Górna część mięśni czworobocznych", "Szrugsy z hantlami", null },
                    { 20, "Shoulders", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań ze sztangą opartą o przednią część barków, chwyt nieco szerszy niż barki. Napnij pośladki i brzuch, a następnie wypchnij sztangę pionowo nad głowę do wyprostu łokci, odsuwając lekko głowę, by zrobić miejsce dla gryfu. Nie wyginaj pleców w łuk.", "Intermediate", "Barbell", false, "Przedni i boczny akton barków, triceps, górna część klatki piersiowej", "Wyciskanie sztangi nad głowę stojąc", null },
