                    { 22, "Shoulders", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań z hantlami przy biodrach i lekko ugiętymi łokciami. Unieś ramiona bokiem do wysokości barków, prowadząc ruch łokciami, i powoli je opuść. Nie bujaj tułowiem.", "Beginner", "Dumbbell", false, "Boczny akton barków", "Wznosy hantli bokiem", null },
                    { 23, "Shoulders", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań prosto z hantlami przed udami. Unieś jedną lub obie ręce przed siebie do wysokości barków, z lekko ugiętymi łokciami, i powoli je opuść.", "Beginner", "Dumbbell", false, "Przedni akton barków", "Wznosy hantli w przód", null },
                    { 24, "Shoulders", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Pochyl tułów prawie równolegle do podłogi, hantle trzymaj pod klatką piersiową. Unieś ramiona szeroko na boki z lekko ugiętymi łokciami, aż znajdą się w linii z tułowiem, i powoli je opuść.", "Beginner", "Dumbbell", false, "Tylny akton barków, mięśnie równoległoboczne", "Odwrotne rozpiętki w opadzie tułowia", null },
