                    { 26, "Shoulders", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Usiądź z hantlami przed twarzą, dłonie zwrócone do siebie. Wypychając hantle nad głowę, obróć dłonie na zewnątrz, aby na górze były skierowane do przodu. Wróć tym samym ruchem.", "Intermediate", "Dumbbell", false, "Przedni i boczny akton barków, triceps", "Arnoldki", null },
