                    { 35, "Arms", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ułóż dłonie blisko siebie pod klatką piersiową, tak by kciuki i palce wskazujące tworzyły romb. Opuść się, prowadząc łokcie wzdłuż tułowia, i wypchnij się do wyprostu ramion.", "Intermediate", "Bodyweight", false, "Triceps, klatka piersiowa", "Pompki diamentowe", null },
