                    { 45, "Legs", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Oprzyj górną część pleców o ławkę, sztangę połóż na biodrach (najlepiej na podkładce). Wypchnij biodra w górę, aż tułów i uda utworzą linię prostą, zaciśnij pośladki i powoli opuść biodra.", "Intermediate", "Barbell", false, "Pośladki, mięśnie dwugłowe ud", "Unoszenie bioder ze sztangą (hip thrust)", null },
                    { 46, "Legs", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań przodostopiem na krawędzi podwyższenia, z ramionami maszyny na barkach. Opuść pięty jak najniżej, a następnie wspinaj się na palce jak najwyżej. Ruch wykonuj powoli, bez sprężynowania.", "Beginner", "Machine", false, "Mięśnie łydek", "Wspięcia na palce stojąc", null },
