                    { 58, "Cardio", new DateTimeOffset(new DateTime(2026, 11, 19, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Stań prosto ze złączonymi nogami. W podskoku rozstaw nogi na boki i unieś ręce nad głowę, a w kolejnym podskoku wróć do pozycji wyjściowej. Utrzymuj stałe tempo.", "Beginner", "Bodyweight", false, "Całe ciało, mięśnie łydek", "Pajacyki", null },
